-- D10: professional meal-plan documents use the C6 canonical identity/signature engine.
alter table public.document_artifacts add column if not exists source_key text;
create index if not exists document_artifacts_source_key_idx on public.document_artifacts(source_type,source_key)where source_key is not null;

create function public.create_document_artifact_from_meal_plan(p_plan_id bigint,p_visibility text default'shared_with_patient')returns jsonb language plpgsql security definer set search_path='' as $$declare v_actor uuid:=auth.uid();v_plan public.meal_plans%rowtype;v_episode public.care_episodes%rowtype;v_identity public.professional_document_identities%rowtype;v_responsible uuid;v_id uuid;v_payload jsonb;begin if v_actor is null then raise exception using errcode='42501',message='authentication_required';end if;if p_visibility not in('professional_private','shared_with_patient','share_later')then raise exception using errcode='22023',message='invalid_document_visibility';end if;select*into v_plan from public.meal_plans where id=p_plan_id;select*into v_episode from public.care_episodes where id=v_plan.care_episode_id;if v_plan.id is null or v_plan.is_draft or v_plan.prescription_status in('archived','invalidated')or not private.can_write_active_care_episode(v_plan.care_episode_id)or v_actor not in(v_plan.nutritionist_id,coalesce(v_episode.student_id,v_plan.nutritionist_id),coalesce(v_episode.supervisor_id,v_plan.nutritionist_id))then raise exception using errcode='42501',message='meal_plan_document_forbidden';end if;v_responsible:=coalesce(v_episode.supervisor_id,v_plan.nutritionist_id);select*into v_identity from public.professional_document_identities where professional_id=v_responsible and status='active';if not found then raise exception using errcode='23514',message='responsible_document_identity_required';end if;if exists(select 1 from public.document_artifacts where source_type='meal_plan'and source_key=p_plan_id::text and status in('draft','finalized','signed'))then raise exception using errcode='23505',message='meal_plan_document_already_exists';end if;select jsonb_build_object('title','PLANO ALIMENTAR','plan_name',v_plan.name,'issued_on',current_date,'diet_characteristics',jsonb_strip_nulls(jsonb_build_object('mode',v_plan.plan_mode,'description',v_plan.description,'active_days',v_plan.active_days,'start_date',v_plan.start_date,'end_date',v_plan.end_date)),'nutritional_targets',jsonb_build_object('energy_kcal',v_plan.daily_calories,'protein_g',v_plan.daily_protein,'carbohydrate_g',v_plan.daily_carbs,'fat_g',v_plan.daily_fat),'meals',coalesce((select jsonb_agg(jsonb_build_object('name',m.name,'type',m.meal_type,'time',m.meal_time,'notes',m.notes,'foods',coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('name',coalesce(f.food_snapshot->>'name',fd.name),'quantity',f.quantity,'unit',f.unit,'patient_description',f.patient_description,'calories',f.calories,'protein',f.protein,'carbs',f.carbs,'fat',f.fat,'source',coalesce(f.food_snapshot->>'source',fd.source)))order by f.order_index,f.id)from public.meal_plan_foods f left join public.foods fd on fd.id=f.food_id where f.meal_plan_meal_id=m.id),'[]'::jsonb))order by m.order_index,m.id)from public.meal_plan_meals m where m.meal_plan_id=v_plan.id),'[]'::jsonb),'professional_confirmation',jsonb_build_object('responsible_id',v_responsible,'prepared_by',v_actor),'source_snapshot',v_plan.source_snapshot)into v_payload;insert into public.document_artifacts(layout_code,layout_version,source_type,source_key,patient_id,care_episode_id,professional_id,preparer_id,supervisor_id,identity_id,visibility,draft_payload)values('meal_plan',1,'meal_plan',p_plan_id::text,v_plan.patient_id,v_plan.care_episode_id,v_responsible,v_actor,v_episode.supervisor_id,v_identity.id,p_visibility,v_payload)returning id into v_id;insert into public.document_artifact_events(artifact_id,actor_id,event_type,to_status,reason)values(v_id,v_actor,'created','draft','document_created_from_meal_plan');return jsonb_build_object('artifact_id',v_id,'status','draft','revision',1,'source_key',p_plan_id::text);end$$;

create or replace function public.get_document_artifact(p_artifact_id uuid)returns jsonb language plpgsql stable security definer set search_path='' as $$declare v_a public.document_artifacts%rowtype;begin if auth.uid()is null then raise exception using errcode='42501',message='authentication_required';end if;select*into v_a from public.document_artifacts where id=p_artifact_id;if not found then raise exception using errcode='P0002',message='document_artifact_not_found';end if;if auth.uid()=v_a.patient_id then if v_a.status not in('signed','invalidated','superseded')or v_a.visibility<>'shared_with_patient'then raise exception using errcode='42501',message='document_artifact_read_forbidden';end if;elsif auth.uid()not in(v_a.professional_id,v_a.preparer_id,coalesce(v_a.supervisor_id,v_a.professional_id))then raise exception using errcode='42501',message='document_artifact_read_forbidden';end if;return jsonb_strip_nulls(jsonb_build_object('id',v_a.id,'status',v_a.status,'visibility',v_a.visibility,'revision',v_a.revision,'source_type',v_a.source_type,'source_id',v_a.source_id,'source_key',v_a.source_key,'patient_id',v_a.patient_id,'care_episode_id',v_a.care_episode_id,'professional_id',v_a.professional_id,'preparer_id',v_a.preparer_id,'supervisor_id',v_a.supervisor_id,'canonical_payload',v_a.canonical_payload,'sha256',v_a.canonical_sha256,'signed_at',v_a.signed_at,'authenticity_code',v_a.authenticity_code,'invalidation_reason',v_a.invalidation_reason));end$$;

revoke all on function public.create_document_artifact_from_meal_plan(bigint,text)from public,anon,authenticated;grant execute on function public.create_document_artifact_from_meal_plan(bigint,text)to authenticated,service_role;
